    89  {
    90    static inline void process_op (OpCode op, InterpEnv<Number>& env)
    91    {
    92      switch (op) {
    93        case OpCode_longintdict:  /* 5-byte integer */
    94          env.argStack.push_longint_from_substr (env.substr);
    95          break;
    96
    97        case OpCode_BCD:  /* real number */
    98          env.argStack.push_real (parse_bcd (env.substr));
    99          break;
   100
