   107    static inline double parse_bcd (SubByteStr& substr)
   108    {
   109      bool    neg = false;
   110      double  int_part = 0;
   111      uint64_t frac_part = 0;
   112      uint32_t  frac_count = 0;
   113      bool    exp_neg = false;
   114      uint32_t  exp_part = 0;
   115      bool    exp_overflow = false;
   116      enum Part { INT_PART=0, FRAC_PART, EXP_PART } part = INT_PART;
   117      enum Nibble { DECIMAL=10, EXP_POS, EXP_NEG, RESERVED, NEG, END };
   118      const uint64_t MAX_FRACT = 0xFFFFFFFFFFFFFllu; /* 1^52-1 */
   119      const uint32_t MAX_EXP = 0x7FFu; /* 1^11-1 */
   120
   121      double  value = 0.0;
   122      unsigned char byte = 0;
   123      for (uint32_t i = 0;; i++)
   124      {
   125        char d;
   126        if ((i & 1) == 0)
   127        {
   128          if (!substr.avail ())
   129          {
   130            substr.set_error ();
   131            return 0.0;
   132          }
   133          byte = substr[0];
   134          substr.inc ();
   135          d = byte >> 4;
   136        }
   137        else
   138          d = byte & 0x0F;
   139
   140        switch (d)
   141        {
   142          case RESERVED:
   143            substr.set_error ();
   144            return value;
   145
   146          case END:
   147            value = (double)(neg? -int_part: int_part);
   148            if (frac_count > 0)
   149            {
   150              double frac = (frac_part / pow (10.0, (double)frac_count));
   151              if (neg) frac = -frac;
   152              value += frac;
   153            }
   154            if (unlikely (exp_overflow))
   155            {
   156              if (value == 0.0)
   157                return value;
   158              if (exp_neg)
   159                return neg? -DBL_MIN: DBL_MIN;
   160              else
   161                return neg? -DBL_MAX: DBL_MAX;
   162            }
   163            if (exp_part != 0)
   164            {
   165              if (exp_neg)
   166                value /= pow (10.0, (double)exp_part);
   167              else
   168                value *= pow (10.0, (double)exp_part);
   169            }
   170            return value;
   171
   172          case NEG:
   173            if (i != 0)
   174            {
   175              substr.set_error ();
   176              return 0.0;
   177            }
   178            neg = true;
   179            break;
   180
   181          case DECIMAL:
   182            if (part != INT_PART)
   183            {
   184              substr.set_error ();
   185              return value;
   186            }
   187            part = FRAC_PART;
   188            break;
   189
   190          case EXP_NEG:
   191            exp_neg = true;
   192            HB_FALLTHROUGH;
   193
   194          case EXP_POS:
   195            if (part == EXP_PART)
   196            {
   197              substr.set_error ();
   198              return value;
   199            }
   200            part = EXP_PART;
   201            break;
   202
   203          default:
   204            switch (part) {
   205              default:
   206              case INT_PART:
   207                int_part = (int_part * 10) + d;
   208                break;
   209
   210              case FRAC_PART:
   211                if (likely (frac_part <= MAX_FRACT / 10))
   212                {
   213                  frac_part = (frac_part * 10) + (unsigned)d;
   214                  frac_count++;
   215                }
   216                break;
   217
   218              case EXP_PART:
   219                if (likely (exp_part * 10 + d <= MAX_EXP))
   220                {
   221                  exp_part = (exp_part * 10) + d;
   222                }
   223                else
   224                  exp_overflow = true;
   225                break;
   226            }
   227        }
   228      }
   229
   230      return value;
   231    }
