    84  /* CFF INDEX */
    85  template <typename COUNT>
    86  struct CFFIndex
    87  {
    88    inline bool sanitize (hb_sanitize_context_t *c) const
    89    {
    90      TRACE_SANITIZE (this);
    91      return_trace (likely ((count.sanitize (c) && count == 0) || /* empty INDEX */
    92                            (c->check_struct (this) && offSize >= 1 && offSize <= 4 &&
    93                             c->check_array (offsets, offSize, count + 1) &&
    94                             c->check_array ((const HBUINT8*)data_base (), 1, max_offset () - 1))));
    95    }
    96
    97    inline static unsigned int calculate_offset_array_size (unsigned int offSize, unsigned int count)
    98    { return offSize * (count + 1); }
    99
   100    inline unsigned int offset_array_size (void) const
   101    { return calculate_offset_array_size (offSize, count); }
   102
   103    inline static unsigned int calculate_serialized_size (unsigned int offSize, unsigned int count, unsigned int dataSize)
   104    {
   105      if (count == 0)
   106        return COUNT::static_size;
   107      else
   108        return min_size + calculate_offset_array_size (offSize, count) + dataSize;
   109    }
   110
   111    inline bool serialize (hb_serialize_context_t *c, const CFFIndex &src)
   112    {
   113      TRACE_SERIALIZE (this);
   114      unsigned int size = src.get_size ();
   115      CFFIndex *dest = c->allocate_size<CFFIndex> (size);
   116      if (unlikely (dest == nullptr)) return_trace (false);
   117      memcpy (dest, &src, size);
   118      return_trace (true);
   119    }
