   121    inline bool serialize (hb_serialize_context_t *c,
   122                           unsigned int offSize_,
   123                           const ByteStrArray &byteArray)
   124    {
   125      TRACE_SERIALIZE (this);
   126      if (byteArray.len == 0)
   127      {
   128        COUNT *dest = c->allocate_min<COUNT> ();
   129        if (unlikely (dest == nullptr)) return_trace (false);
   130        dest->set (0);
   131      }
   132      else
   133      {
   134        /* serialize CFFIndex header */
   135        if (unlikely (!c->extend_min (*this))) return_trace (false);
   136        this->count.set (byteArray.len);
   137        this->offSize.set (offSize_);
   138        if (!unlikely (c->allocate_size<HBUINT8> (offSize_ * (byteArray.len + 1))))
   139          return_trace (false);
   140
   141        /* serialize indices */
   142        unsigned int  offset = 1;
   143        unsigned int  i = 0;
   144        for (; i < byteArray.len; i++)
   145        {
   146          set_offset_at (i, offset);
   147          offset += byteArray[i].get_size ();
   148        }
   149        set_offset_at (i, offset);
   150
   151        /* serialize data */
   152        for (unsigned int i = 0; i < byteArray.len; i++)
   153        {
   154          ByteStr  *dest = c->start_embed<ByteStr> ();
   155          if (unlikely (dest == nullptr ||
   156                        !dest->serialize (c, byteArray[i])))
   157            return_trace (false);
   158        }
   159      }
   160      return_trace (true);
   161    }
