   163    inline bool serialize (hb_serialize_context_t *c,
   164                           unsigned int offSize_,
   165                           const StrBuffArray &buffArray)
   166    {
   167      ByteStrArray  byteArray;
   168      byteArray.init ();
   169      byteArray.resize (buffArray.len);
   170      for (unsigned int i = 0; i < byteArray.len; i++)
   171      {
   172        byteArray[i] = ByteStr (buffArray[i].arrayZ (), buffArray[i].len);
   173      }
   174      bool result = this->serialize (c, offSize_, byteArray);
   175      byteArray.fini ();
   176      return result;
   177    }
