   179    inline void set_offset_at (unsigned int index, unsigned int offset)
   180    {
   181      HBUINT8 *p = offsets + offSize * index + offSize;
   182      unsigned int size = offSize;
   183      for (; size; size--)
   184      {
   185        --p;
   186        p->set (offset & 0xFF);
   187        offset >>= 8;
   188      }
   189    }
   190
   191    inline unsigned int offset_at (unsigned int index) const
   192    {
   193      assert (index <= count);
   194      const HBUINT8 *p = offsets + offSize * index;
   195      unsigned int size = offSize;
   196      unsigned int offset = 0;
   197      for (; size; size--)
   198        offset = (offset << 8) + *p++;
   199      return offset;
   200    }
   201
   202    inline unsigned int length_at (unsigned int index) const
   203    {
   204          if (likely ((offset_at (index + 1) >= offset_at (index)) &&
   205                      (offset_at (index + 1) <= offset_at (count))))
   206            return offset_at (index + 1) - offset_at (index);
   207          else
   208            return 0;
   209    }
