   211    inline const char *data_base (void) const
   212    { return (const char *)this + min_size + offset_array_size (); }
   213
   214    inline unsigned int data_size (void) const
   215    { return HBINT8::static_size; }
   216
   217    inline ByteStr operator [] (unsigned int index) const
   218    {
   219      if (likely (index < count))
   220        return ByteStr (data_base () + offset_at (index) - 1, length_at (index));
   221      else
   222        return Null(ByteStr);
   223    }
