   225    inline unsigned int get_size (void) const
   226    {
   227      if (this != &Null(CFFIndex))
   228      {
   229        if (count > 0)
   230          return min_size + offset_array_size () + (offset_at (count) - 1);
   231        else
   232          return count.static_size;  /* empty CFFIndex contains count only */
   233      }
   234      else
   235        return 0;
   236    }
